-- Authoritative schema. Do not edit an applied migration; add V2, V3, etc.
-- IDs remain scalar API fields; foreign keys are enforced here, not by JPA associations.
CREATE TABLE users (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role VARCHAR(255) NOT NULL CHECK (role IN ('CANDIDATE', 'COMPANY', 'ADMIN')),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE candidates (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INTEGER NOT NULL UNIQUE REFERENCES users(id),
    full_name VARCHAR(255) NOT NULL,
    phone VARCHAR(255), location VARCHAR(255), experience VARCHAR(255)
);
CREATE TABLE companies (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INTEGER NOT NULL UNIQUE REFERENCES users(id),
    company_name VARCHAR(255) NOT NULL,
    industry VARCHAR(255), address VARCHAR(255), approved BOOLEAN DEFAULT FALSE
);
CREATE TABLE jobs (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id INTEGER NOT NULL REFERENCES companies(id),
    title VARCHAR(255) NOT NULL,
    description TEXT, skills_required TEXT, salary_range VARCHAR(255),
    location VARCHAR(255), employment_type VARCHAR(255),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    latitude DOUBLE PRECISION, longitude DOUBLE PRECISION,
    min_salary INTEGER, max_salary INTEGER, category VARCHAR(255),
    status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'CLOSED', 'DRAFT')),
    starts_at TIMESTAMP, ends_at TIMESTAMP,
    CONSTRAINT jobs_salary_bounds CHECK ((min_salary IS NULL OR min_salary >= 0) AND
        (max_salary IS NULL OR max_salary >= 0) AND
        (min_salary IS NULL OR max_salary IS NULL OR min_salary <= max_salary)),
    CONSTRAINT jobs_coordinates CHECK ((latitude IS NULL AND longitude IS NULL) OR
        (latitude IS NOT NULL AND longitude IS NOT NULL AND latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180))
);
CREATE TABLE resumes (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    candidate_id INTEGER NOT NULL REFERENCES candidates(id),
    file_path VARCHAR(500) NOT NULL,
    uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE applications (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    candidate_id INTEGER NOT NULL REFERENCES candidates(id),
    job_id INTEGER NOT NULL REFERENCES jobs(id),
    status VARCHAR(255) DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED', 'REVIEWED', 'SHORTLISTED', 'REJECTED', 'HIRED')),
    applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT applications_candidate_job_unique UNIQUE(candidate_id, job_id)
);
CREATE TABLE interview_slots (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_id INTEGER NOT NULL REFERENCES jobs(id),
    candidate_id INTEGER REFERENCES candidates(id),
    starts_at TIMESTAMP NOT NULL, ends_at TIMESTAMP NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'SCHEDULED',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT slots_ordered_interval CHECK (ends_at > starts_at)
);
-- Tracks synthetic record identity independently of table sequence values.
-- Entries may outlive deleted demo records so a later run can recreate just those records.
CREATE TABLE demo_seed_records (
    seed_key VARCHAR(160) PRIMARY KEY,
    resource_type VARCHAR(30) NOT NULL,
    resource_id BIGINT NOT NULL,
    CONSTRAINT seed_resource_unique UNIQUE(resource_type, resource_id)
);
CREATE INDEX idx_jobs_company ON jobs(company_id);
CREATE INDEX idx_jobs_title ON jobs(title);
CREATE INDEX idx_jobs_location ON jobs(location);
CREATE INDEX idx_jobs_status_category ON jobs(status, category);
CREATE INDEX idx_jobs_coordinates ON jobs(latitude, longitude);
CREATE INDEX idx_applications_job ON applications(job_id);
CREATE INDEX idx_applications_status ON applications(status);
CREATE INDEX idx_resumes_candidate ON resumes(candidate_id);
CREATE INDEX idx_slots_job_time ON interview_slots(job_id, starts_at, ends_at);
CREATE INDEX idx_slots_candidate ON interview_slots(candidate_id);
-- A single row serializes seed runs and prevents mixing different random/time configurations.
CREATE TABLE demo_seed_state (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    random_seed BIGINT,
    base_time TIMESTAMP
);
INSERT INTO demo_seed_state(id) VALUES (1);
